    const val H = 1080f

    // Main kitten body (without upper tail, ears and near legs) and its parts
    const val KITTEN_X = 655f; const val KITTEN_Y = 282f
    const val TAIL_X = 1199f; const val TAIL_Y = 104f
    const val TAIL_PIVOT_X = 1292f; const val TAIL_PIVOT_Y = 317f
    const val EAR_L_X = 755f; const val EAR_L_Y = 259f; const val EAR_L_PX = 804f; const val EAR_L_PY = 335f
    const val EAR_R_X = 926f; const val EAR_R_Y = 257f; const val EAR_R_PX = 997f; const val EAR_R_PY = 358f
    const val LEG_F_X = 825f; const val LEG_F_Y = 559f
    const val LEG_H_X = 1211f; const val LEG_H_Y = 525f
    // Eyes: iris + shine pieces and the sockets they are clipped to (cx, cy, rx, ry)
    const val IRIS_L_X = 764f; const val IRIS_L_Y = 440f
    const val IRIS_R_X = 867f; const val IRIS_R_Y = 456f
    val SOCKET_L = floatArrayOf(783f, 466f, 22f, 29f)
    val SOCKET_R = floatArrayOf(901f, 482f, 32f, 29f)
    /** Between the eyes (kitten-local art px). */
    const val EYES_X = 842f; const val EYES_Y = 474f
    const val FEET_Y = 672f
    /** Mirror axis of the kitten (its centre). */
    const val FLIP_X = 1006f
    /** Raised paw tip, relative to the mirror axis when facing left. */
    const val PAW_TIP = -331f
    /** How far the kitten may walk from its home spot (keeps it on screen). */
    const val WALK_MIN = -470f
    /** Offset that puts the kitten in the middle of the screen. */
    const val CENTER_WALK = 960f - 1006f
    const val WALK_MAX = 500f

    const val SLEEPER_X = 1378f; const val SLEEPER_Y = 408f

    const val BALL_R = 70f
    const val BALL_PAD = 6f
    const val BALL_Y = 636f

    const val TILE_W = 200f; const val TILE_H = 186f
    const val TILE_GLOW = 44f
    const val ROW_TOP = 711f
    const val ROW_START = 55f
    const val ROW_GAP = 38f
}

/** All bitmaps of the scene, decoded once. */
class SceneAssets(
    val room: ImageBitmap,
    val kitten: ImageBitmap,
    val tail: ImageBitmap,
    val earL: ImageBitmap,
    val earR: ImageBitmap,
    val legF: ImageBitmap,
    val legH: ImageBitmap,
    val irisL: ImageBitmap,
    val irisR: ImageBitmap,
    val blink: ImageBitmap,
    val sleeper: ImageBitmap,
    val ball: ImageBitmap,
    val ballShade: ImageBitmap,
    val glow: ImageBitmap,
) {
    companion object {
        fun load(context: Context): SceneAssets {
            fun img(path: String) = decode(context, path).asImageBitmap()
            return SceneAssets(
                room = img("bg/room.webp"),
                kitten = img("cat/kitten.png"),
                tail = img("cat/tail.png"),
                earL = img("cat/ear_l.png"),
                earR = img("cat/ear_r.png"),
                legF = img("cat/leg_f.png"),
                legH = img("cat/leg_h.png"),
                irisL = img("cat/eye_l_iris.png"),
                irisR = img("cat/eye_r_iris.png"),
                blink = img("cat/blink.png"),
                sleeper = img("cat/sleeper.png"),
                ball = img("ball/ball.png"),
                ballShade = img("ball/shade.png"),
                glow = img("tiles/glow.png"),
            )
        }

        fun decode(context: Context, path: String): Bitmap =
            context.assets.open(path).use {
                BitmapFactory.decodeStream(it, null, BitmapFactory.Options().apply {
                    inPreferredConfig = Bitmap.Config.ARGB_8888
                    inScaled = false
                })!!
            }
    }
}
